import { chromium } from '/home/node/.npm/_npx/420ff84f11983ee5/node_modules/playwright/index.mjs';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1440, height: 1000}, deviceScaleFactor: 1});
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:5175/', {waitUntil:'networkidle'});
await page.evaluate(() => document.fonts.ready);
await page.screenshot({path:'/tmp/orbita-desktop.png',fullPage:true});
console.log('Initial layout', await page.evaluate(() => ({height:document.body.scrollHeight,width:document.body.scrollWidth,font:getComputedStyle(document.querySelector('.app-shell')).fontFamily,main:document.querySelector('main').getBoundingClientRect().toJSON()})));
assert.equal(await page.getByRole('heading', {level:1}).textContent(),'Всё начинается с идеи.');
await page.getByRole('button',{name:'Тёмная тема',exact:true}).click();
assert.equal(await page.locator('html').getAttribute('data-theme'),'dark');
await page.getByRole('link',{name:'Проекты',exact:true}).click();
await page.getByRole('heading',{name:'Мои проекты',exact:true}).waitFor();
await page.reload();
assert.equal(await page.locator('html').getAttribute('data-theme'),'dark');
await page.screenshot({path:'/tmp/orbita-dark.png',fullPage:true});
await page.getByRole('button',{name:'Новый проект',exact:true}).click();
await page.getByLabel('Название проекта').fill('Тестовый запуск');
await page.getByLabel('Пару слов о проекте').fill('Проверка полного сценария');
await page.getByLabel('Когда планируете закончить?').fill('2026-12-01');
await page.getByRole('button',{name:'Зелёный',exact:true}).click();
await page.getByRole('button',{name:'Создать проект',exact:true}).click();
await page.locator('.project-card').filter({hasText:'Тестовый запуск'}).click();
await page.getByLabel('Новая задача').fill('Первый шаг');
await page.getByRole('button',{name:'Добавить задачу',exact:true}).click();
await page.getByRole('checkbox',{name:'Первый шаг',exact:true}).check();
await page.getByRole('button',{name:'Готово',exact:true}).click();
await page.getByRole('button',{name:'Завершённые',exact:true}).click();
assert.equal(await page.locator('.project-card').count(),1);
assert.match(await page.locator('.project-card').textContent(),/100%/);
await page.getByRole('button',{name:'Все проекты 4',exact:true}).click();
await page.getByRole('textbox',{name:'Найти проект',exact:true}).fill('такого нет');
assert.equal(await page.locator('.project-card').count(),0);
await page.getByRole('heading',{name:'Ничего не нашлось',exact:true}).waitFor();
await page.getByRole('link',{name:'Заметки',exact:true}).click();
await page.getByRole('heading',{name:'Мои заметки',exact:true}).waitFor();
await page.getByRole('button',{name:'Новая заметка',exact:true}).click();
await page.getByLabel('Заголовок',{exact:true}).fill('Мысль на завтра');
await page.getByLabel('Ваша мысль',{exact:true}).fill('Важная заметка для проверки сохранения.');
await page.getByRole('button',{name:'Закрепить',exact:true}).click();
await page.getByRole('button',{name:'Сохранить заметку',exact:true}).click();
await page.getByRole('button',{name:'Закреплённые',exact:true}).click();
assert.equal(await page.locator('.note-card').count(),2);
await page.locator('.note-card').filter({hasText:'Мысль на завтра'}).click();
await page.getByLabel('Ваша мысль',{exact:true}).fill('Обновлённая мысль');
await page.getByRole('button',{name:'Сохранить заметку',exact:true}).click();
await page.reload();
await page.locator('.note-card').filter({hasText:'Мысль на завтра'}).waitFor();
assert.match(await page.locator('.note-card').filter({hasText:'Мысль на завтра'}).textContent(),/Обновлённая мысль/);
await page.locator('.note-card').filter({hasText:'Мысль на завтра'}).click();
await page.keyboard.press('Escape');
assert.equal(await page.getByRole('dialog').count(),0);
await page.getByRole('link',{name:'Обзор',exact:true}).click();
await page.getByRole('button',{name:/Начать фокус/}).click();
await page.waitForTimeout(1200);
assert.match(await page.locator('.focus-button').textContent(),/24:59/);
await page.getByRole('button',{name:/Пауза/}).click();
await page.getByRole('button',{name:'Сбросить таймер'}).click();
assert.match(await page.locator('.focus-button').textContent(),/25:00/);
await page.getByRole('button',{name:'Светлая тема',exact:true}).click();
await page.evaluate(() => {localStorage.clear();});
await page.reload();
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/orbita-mobile.png',fullPage:true});
for (const route of ['overview','projects','notes']) {
  await page.getByRole('link',{name:{overview:'Обзор',projects:'Проекты',notes:'Заметки'}[route],exact:true}).click();
  const dimensions = await page.evaluate(() => ({scroll:document.documentElement.scrollWidth,viewport:innerWidth}));
  assert.ok(dimensions.scroll <= dimensions.viewport, "'`${route} overflow ${JSON.stringify(dimensions)}`);
}
await page.getByRole('"'button',{name:'Новая заметка',exact:true}).click();
assert.ok(await page.getByRole('dialog').isVisible());
await page.screenshot({path:'/tmp/orbita-mobile-modal.png',fullPage:true});
await page.keyboard.press('Escape');
assert.deepEqual(errors,[]);
console.log('PASS: 3-page navigation, theme persistence, project creation, tasks, filters, search, notes create/edit/pin/persist, modal keyboard, focus timer and mobile overflow.');
await browser.close();
EOF"

